// 1. Recorremos todos los items de entrada para capturar datos de ambas ramas
const allItems = $input.all();

let cvText = "";
let jobData = {};
let bodyData = {};

for (const item of allItems) {
  const json = item.json;
  if (json.text || json.textExtracted) {
    cvText = String(json.text || json.textExtracted || "").slice(0, 8000);
  }
  if (json.title || json.description) {
    jobData = json;
  }
  if (json.body) {
    bodyData = json.body;
  }
}

// 2. Fallback al webhook para candidate_id y job_id
try {
  const wh = $('Webhook1').item.json;
  bodyData = wh.body || wh;
} catch (_) {}

// 3. Construimos el objeto plano final
const resultadoPlano = {
  cv_text: cvText,
  job_title: String(jobData.title || ""),
  job_description: String(jobData.description || ""),
  job_requirements: String(jobData.requirements || ""),
  job_skills: Array.isArray(jobData.skills_required || jobData.skills) ? (jobData.skills_required || jobData.skills) : [],
  candidate_id: String(bodyData.candidate_id || ""),
  job_id: String(bodyData.job_id || ""),
  _execution_start_ms: Date.now()
};

// 4. Retornamos
return [{ json: resultadoPlano }];

const llmOutput = $input.first().json;

let jsonResult;
try {
  if (llmOutput.summary && llmOutput.seniority && llmOutput.score !== undefined) {
    jsonResult = llmOutput;
  } else if (typeof llmOutput.output === "string") {
    const cleaned = llmOutput.output.replace(/```json\s*/g, "").replace(/```\s*/g, "").trim();
    jsonResult = JSON.parse(cleaned);
  } else if (typeof llmOutput.output === "object" && llmOutput.output !== null) {
    jsonResult = llmOutput.output;
  } else {
    throw new Error("Formato inesperado del LLM: " + JSON.stringify(Object.keys(llmOutput)));
  }

  const err = validateLLMResult(jsonResult);
  if (err) throw new Error(err);

  const merged = $("Merge CV & Job").first().json;

  return [{
    candidate_id: merged.candidate_id,
    job_id: merged.job_id,
    ai_summary: String(jsonResult.summary),
    json_result: JSON.parse(JSON.stringify(jsonResult)),
    model_version: "deepseek-chat",
    prompt_tokens: llmOutput.usage?.prompt_tokens || 0,
    completion_tokens: llmOutput.usage?.completion_tokens || 0
  }];
} catch (error) {
  const merged = $("Merge CV & Job").first().json;
  return [{
    candidate_id: merged.candidate_id,
    job_id: merged.job_id,
    ai_summary: "Error en analisis IA",
    json_result: {
      summary: "Error en analisis IA",
      seniority: null,
      score: 0,
      classification: [],
      suggestions: "HOLD: Error del LLM - " + error.message,
      riskLevel: "Medium"
    },
    model_version: "deepseek-chat",
    prompt_tokens: 0,
    completion_tokens: 0
  }];
}

function validateLLMResult(r) {
  if (!r || typeof r !== "object") return "Resultado no es un objeto";
  if (typeof r.summary !== "string" || !r.summary) return "summary invalido";
  const VALID_SEN = ["Junior", "Semi-Senior", "Senior"];
  if (!VALID_SEN.includes(r.seniority)) return "seniority invalido: " + r.seniority;
  if (typeof r.score !== "number" || r.score < 0 || r.score > 100) return "score invalido: " + r.score;
  if (!Array.isArray(r.classification)) return "classification invalido";
  const validPrefixes = ["ADVANCE:", "INTERVIEW:", "TEST:", "HOLD:", "DISCARD:"];
  if (typeof r.suggestions !== "string" || !validPrefixes.some(function(p) { return r.suggestions.startsWith(p); })) {
    return "suggestions debe empezar con " + validPrefixes.join(", ");
  }
  const VALID_RISK = ["Low", "Medium", "High"];
  if (!VALID_RISK.includes(r.riskLevel)) return "riskLevel invalido: " + r.riskLevel;
  return null;
}

