={{ 
  (() => {
    // 1. Extraemos el json_result base
    let result = $json.json_result || {};

    // 2. Si viene como un string (JSON serializado), lo parseamos de forma segura
    if (typeof result === 'string') {
      try { result = JSON.parse(result); } catch(_) { result = {}; }
    }

    // --- PARACAÍDAS 1: Seniority (Estricto String) ---
    const validSeniorities = ["Junior", "Semi-Senior", "Senior"];
    let currentSeniority = result.seniority || $json.seniority || "";
    if (!validSeniorities.includes(currentSeniority)) {
      currentSeniority = "Junior"; 
    }

    // --- PARACAÍDAS 2: Classification (Estricto Array no vacío) ---
    let currentClassification = result.classification || $json.classification;
    // Si no es un array, intentamos convertirlo o creamos uno por defecto
    if (!Array.isArray(currentClassification)) {
      if (typeof currentClassification === 'string' && currentClassification.trim() !== "") {
        currentClassification = [currentClassification];
      } else {
        currentClassification = ["General"]; // Valor por defecto si la IA no mandó nada
      }
    }
    // Si es un array pero está vacío, le metemos un string por defecto
    if (currentClassification.length === 0) {
      currentClassification = ["General"];
    }

    // 3. Reconstruimos el objeto json_result totalmente limpio y blindado
    const cleanJsonResult = {
      ...result,
      seniority: currentSeniority,
      classification: currentClassification.map(item => String(item)) // Nos aseguramos que sean strings
    };

    // 4. Retornamos el stringify final estructurado para Next.js
    return JSON.stringify({
      "candidate_id": $json.candidate_id,
      "job_id": $json.job_id,
      "ai_summary": $json.ai_summary || cleanJsonResult.summary || "No summary provided.",
      "json_result": cleanJsonResult,
      "model_version": $json.model_version || "deepseek-r1",
      "prompt_tokens": $json.prompt_tokens || 0,
      "completion_tokens": $json.completion_tokens || 0,
      "latency_ms": $json.latency_ms || Math.max(0, Date.now() - ($json._execution_start_ms || Date.now()))
    });
  })()
}}
